func TestEnumCreateMessageRequestAuthor(t *testing.T) {
	t.Run("NewFromString_user", func(t *testing.T) {
		t.Parallel()
		val, err := NewCreateMessageRequestAuthorFromString("user")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CreateMessageRequestAuthor("user"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_assistant", func(t *testing.T) {
		t.Parallel()
		val, err := NewCreateMessageRequestAuthorFromString("assistant")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CreateMessageRequestAuthor("assistant"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_system", func(t *testing.T) {
		t.Parallel()
		val, err := NewCreateMessageRequestAuthorFromString("system")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CreateMessageRequestAuthor("system"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewCreateMessageRequestAuthorFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewCreateMessageRequestAuthorFromString("user")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

